node -e '
for (const f of ["mastodon","bluesky"]) {
  const j = JSON.parse(require("fs").readFileSync(`social-media/temp/${f}.json`,"utf8"));
  const cap = f === "mastodon" ? 500 : 290;
  j.parts.forEach((p,i)=>console.log(`${f} part ${i+1}: ${[...p].length} chars (cap ${cap}) ${[...p].length<=cap?"OK":"OVER"}`));
}'

